import argparse
import json
import sqlite3
import pickle
import sys
from typing import Dict, Any, List, Optional

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('--rules', required=True, help='Path to rules JSON file')
    parser.add_argument('--db', required=True, help='Path to SQLite database file')
    parser.add_argument('--cache', required=True, help='Path to cache file for rule objects')
    return parser.parse_args()

def load_rules_from_json(rules_file: str) -> List[Dict[str, Any]]:
    with open(rules_file, 'r') as f:
        return json.load(f)

def save_rules_to_cache(rules: List[Dict[str, Any]], cache_file: str):
    with open(cache_file, 'wb') as f:
        pickle.dump(rules, f)

def load_rules_from_cache(cache_file: str) -> Optional[List[Dict[str, Any]]]:
    try:
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    except (FileNotFoundError, pickle.UnpicklingError):
        return None

def execute_query(db_conn: sqlite3.Connection, table: str, where: Dict[str, Any]) -> List[Dict[str, Any]]:
    query = "SELECT * FROM {} WHERE ".format(table)
    conditions = []
    params = []
    for col, val in where.items():
        conditions.append("{0} = ?".format(col))
        params.append(val)
    query += " AND ".join(conditions)
    cursor = db_conn.cursor()
    cursor.execute(query, params)
    columns = [desc[0] for desc in cursor.description]
    rows = cursor.fetchall()
    return [dict(zip(columns, row)) for row in rows]

def evaluate_output(row: Dict[str, Any], output_expr: str) -> str:
    try:
        local_vars = {k: v for k, v in row.items()}
        return str(eval(output_expr, {}, local_vars))
    except Exception as e:
        raise ValueError(f"Error evaluating output expression: {e}")

def process_rules(rules: List[Dict[str, Any]], db_file: str):
    conn = sqlite3.connect(db_file)
    for rule in rules:
        try:
            where = rule['where']
            table = rule['table']
            output = rule['output']
            rows = execute_query(conn, table, where)
            for row in rows:
                value = evaluate_output(row, output)
                print(json.dumps({"rule": rule['name'], "value": value}))
        finally:
            conn.close()

def main():
    args = parse_arguments()
    cache_rules = load_rules_from_cache(args.cache)
    if cache_rules is None:
        rules = load_rules_from_json(args.rules)
        save_rules_to_cache(rules, args.cache)
    else:
        rules = cache_rules
    process_rules(rules, args.db)

if __name__ == "__main__":
    main()
